import React, { useEffect, useMemo, useState } from "react";
import { CronExpressionParser } from "cron-parser";
import { ArchiveRestore, Bot, Check, CircleAlert, Clock3, ExternalLink, FileText, Plus, RefreshCw, ServerCog, Settings2, X } from "lucide-react";

const STATE_LABELS = { healthy: "Healthy", on_schedule: "On schedule", running: "Running", degraded: "Degraded", offline: "Offline", overdue: "Overdue", unknown: "Unknown", paused: "Paused", manual: "Manual" };
const STATE_ORDER = { overdue: 0, offline: 1, degraded: 2, unknown: 3, paused: 4, running: 5, healthy: 6, on_schedule: 6, manual: 7 };
const EVENT_LABELS = { status_check_succeeded: "Status check succeeded", status_check_failed: "Status check failed", state_changed: "State changed", bot_became_stale: "Bot became stale", platform_identity_verified: "Platform identity verified", job_scheduled: "Job scheduled", job_started: "Job started", job_succeeded: "Job succeeded", job_failed: "Job failed", job_skipped: "Job skipped", job_cancelled: "Job cancelled", job_became_overdue: "Job became overdue", configuration_updated: "Configuration updated", monitoring_paused: "Monitoring paused", monitoring_resumed: "Monitoring resumed" };
const SCHEDULER_SOURCES = ["Internal bot scheduler", "Windows Task Scheduler", "GitHub Actions", "Hosting-provider cron", "External automation", "Manual", "Unknown"];

function exactTime(value, timezone) {
  if (!value) return "Never";
  const date = new Date(value); if (Number.isNaN(date.getTime())) return "Invalid time";
  return new Intl.DateTimeFormat(undefined, { dateStyle: "medium", timeStyle: "short", timeZone: timezone || undefined }).format(date);
}
function relativeTime(value, reference = new Date()) {
  if (!value) return "Never";
  const difference = new Date(value).getTime() - reference.getTime();
  if (!Number.isFinite(difference)) return "Unknown";
  const absolute = Math.abs(difference); let divisor = 1000; let unit = "second";
  if (absolute >= 86_400_000) { divisor = 86_400_000; unit = "day"; }
  else if (absolute >= 3_600_000) { divisor = 3_600_000; unit = "hour"; }
  else if (absolute >= 60_000) { divisor = 60_000; unit = "minute"; }
  return new Intl.RelativeTimeFormat(undefined, { numeric: "auto" }).format(Math.round(difference / divisor), unit);
}
function duration(value) {
  if (value == null) return "No data yet";
  if (value < 1000) return `${value} ms`;
  if (value < 60_000) return `${(value / 1000).toFixed(value < 10_000 ? 1 : 0)} s`;
  return `${Math.round(value / 60_000)} min`;
}
function stateOf(bot) { return bot?.derivedState?.state || "unknown"; }
function platformLabel(platforms = []) { return platforms.map((value) => value === "discord" ? "Discord" : "Telegram").join(" + ") || "Not configured"; }
function stateBadge(bot) {
  const state = stateOf(bot);
  return <span className={`bot-state state-${state}`}>{STATE_LABELS[state] || state}</span>;
}
function makeId() { return globalThis.crypto?.randomUUID?.() || `local-${Date.now()}-${Math.random().toString(36).slice(2)}`; }
function defaultMonitoring() { return { adapter: "manual", url: "", filePath: "", httpMethod: "GET", authSecretRef: "", intervalSeconds: 60, timeoutMilliseconds: 5000, staleAfterSeconds: 180, failuresBeforeOffline: 3, monitoringEnabled: true, expectedResponseCode: "" }; }
function defaultConnection(platform) { return { id: makeId(), platform, externalBotId: "", username: "", displayName: "", avatarUrl: "", credentialSecretRef: "", credentialState: "not_configured", credentialVerifiedAt: null, credentialErrorSummary: "", installPermissions: "0" }; }
function defaultJob(timezone) { return { id: makeId(), name: "", description: "", scheduleType: "cron", cronExpression: "0 9 * * *", intervalSeconds: 3600, oneTimeAt: "", timezone, enabled: true, critical: false, schedulerSource: "Unknown", schedulerUrl: "", expectedDurationSeconds: 300, gracePeriodSeconds: 600, retryDescription: "", authoritativeNextRunAt: "", logsLocation: "", archivedAt: null }; }
function defaultCommand(platform = "discord") { return { id: makeId(), platform, command: "", description: "", usage: "", parameters: "", permission: "", category: "General", enabled: true, deprecated: false, notes: "" }; }
function newDraft() {
  const timezone = Intl.DateTimeFormat().resolvedOptions().timeZone || "UTC";
  return { name: "", description: "", platforms: ["discord"], executionMode: "continuous", environment: "development", enabled: true, tags: [], repositoryUrl: "", localProjectPath: "", deploymentUrl: "", hostingProvider: "", runtime: "", version: "", logsLocation: "", schedulerSource: "Unknown", schedulerUrl: "", monitoring: defaultMonitoring(), connections: [defaultConnection("discord")], jobs: [], commands: [], mcpServerIds: [], skillIds: [], timezone };
}
function editableBot(bot) {
  if (!bot) return newDraft();
  const copy = structuredClone(bot);
  delete copy.runtime; delete copy.derivedState; delete copy.archivedAt; delete copy.createdAt; delete copy.updatedAt;
  copy.runtime = bot.runtimeLanguage || "";
  copy.monitoring = { ...defaultMonitoring(), ...(copy.monitoring || {}) };
  copy.connections = copy.connections || []; copy.jobs = copy.jobs || []; copy.commands = copy.commands || [];
  copy.tags = copy.tags || []; copy.mcpServerIds = copy.mcpServerIds || []; copy.skillIds = copy.skillIds || [];
  return copy;
}
function cronPreview(job) {
  if (job.scheduleType === "manual") return { label: "Manual", values: [] };
  if (job.scheduleType === "external") return { label: job.authoritativeNextRunAt ? "Reported externally" : "Externally scheduled", values: job.authoritativeNextRunAt ? [job.authoritativeNextRunAt] : [] };
  if (job.scheduleType === "oneTime") return { label: "One time", values: job.oneTimeAt ? [job.oneTimeAt] : [] };
  if (job.scheduleType === "interval") {
    const seconds = Number(job.intervalSeconds); if (!(seconds > 0)) throw new Error("Enter a positive interval.");
    const start = Date.now(); return { label: `Every ${seconds} seconds`, values: [1, 2, 3].map((step) => new Date(start + step * seconds * 1000).toISOString()) };
  }
  if (!job.timezone) throw new Error("Timezone required.");
  const expression = CronExpressionParser.parse(job.cronExpression || "", { currentDate: new Date(), tz: job.timezone });
  return { label: job.cronExpression, values: expression.take(3).map((date) => date.toISOString()) };
}

export function BotSidebar({ bots, currentId, onSelect }) {
  const active = bots.filter((bot) => !bot.archivedAt);
  return <div className="bot-sidebar-list" aria-label="Bot registry shortcuts">
    <div className="bot-sidebar-summary"><strong>{active.length} active</strong><span>{active.filter((bot) => ["overdue", "offline", "degraded"].includes(stateOf(bot))).length} need attention</span></div>
    {active.map((bot) => <button key={bot.id} className={currentId === bot.id ? "active" : ""} onClick={() => onSelect(bot.id)}><span className={`platform-dot ${bot.platforms?.[0] || "unknown"}`}><Bot size={12} /></span><span><strong>{bot.name}</strong><small>{STATE_LABELS[stateOf(bot)] || "Unknown"} · {bot.executionMode}</small></span></button>)}
    {!active.length && <p>No bots yet.</p>}
  </div>;
}

function SummaryStrip({ bots, upcoming }) {
  const active = bots.filter((bot) => !bot.archivedAt);
  const due = upcoming.filter((item) => new Date(item.nextRunAt).getTime() <= Date.now() + 86_400_000).length;
  const values = [
    ["Total", active.length],
    ["Healthy / due", active.filter((bot) => ["healthy", "on_schedule", "running"].includes(stateOf(bot))).length],
    ["Attention", active.filter((bot) => ["degraded", "offline", "overdue"].includes(stateOf(bot))).length],
    ["Unknown", active.filter((bot) => ["unknown", "manual"].includes(stateOf(bot))).length],
    ["Running", active.filter((bot) => stateOf(bot) === "running").length],
    ["Due <24h", due],
  ];
  return <div className="bots-summary" aria-label="Bot status summary">{values.map(([label, value]) => <div key={label}><strong>{value}</strong><span>{label}</span></div>)}</div>;
}

function AttentionArea({ bots, onOpen }) {
  const issues = bots.filter((bot) => !bot.archivedAt).flatMap((bot) => {
    const state = stateOf(bot); const items = [];
    if (["degraded", "offline", "overdue"].includes(state)) items.push({ bot, text: bot.derivedState?.reason || `${STATE_LABELS[state]} status requires attention.` });
    else if (state === "unknown") items.push({ bot, text: bot.derivedState?.reason || "No trustworthy health evidence is available." });
    if (bot.runtime?.isStale) items.push({ bot, text: "Status data is stale; the last useful observation is retained." });
    for (const connection of bot.connections || []) if (connection.credentialState === "invalid") items.push({ bot, text: `${connection.platform === "discord" ? "Discord" : "Telegram"} identity verification failed: ${connection.credentialErrorSummary || "invalid credential"}` });
    return items;
  }).slice(0, 8);
  if (!issues.length) return null;
  return <section className="bots-attention"><header><CircleAlert size={15} /><strong>Needs attention</strong><span>{issues.length}</span></header>{issues.map((issue, index) => <button key={`${issue.bot.id}-${index}`} onClick={() => onOpen(issue.bot.id)}><strong>{issue.bot.name}</strong><span>{issue.text}</span><em>Open</em></button>)}</section>;
}

function UpcomingJobs({ upcoming, onOpen, limit = 5 }) {
  return <section className="upcoming-jobs"><header><div><span className="section-kicker">Across all bots</span><h2>Upcoming jobs</h2></div><span>{upcoming.length ? `${Math.min(limit, upcoming.length)} shown` : "No scheduled jobs"}</span></header>
    <div className="upcoming-list">{upcoming.slice(0, limit).map((item) => <button key={`${item.botId}-${item.job.id}`} onClick={() => onOpen(item.botId)}><span className={`platform-mark ${item.platforms?.[0] || "unknown"}`}>{item.platforms?.[0] === "telegram" ? "T" : "D"}</span><span><strong>{item.job.name}</strong><small>{item.botName} · {item.job.schedulerSource || "Unknown source"}</small></span><span><strong>{relativeTime(item.nextRunAt)}</strong><small>{exactTime(item.nextRunAt, item.job.timezone)} · {item.job.timezone}</small></span><span className={`calculation ${item.nextRunSource}`}>{item.nextRunSource}</span><span className={`job-health state-${item.health?.state || "unknown"}`}>{STATE_LABELS[item.health?.state] || "Unknown"}</span></button>)}</div>
    {!upcoming.length && <p className="bots-section-empty">Event-driven, external without a reported next time, or no scheduled jobs.</p>}
  </section>;
}

function BotRegistry({ bots, upcoming, mcpServers = [], skills = [], notes = [], onOpen, onAdd }) {
  const [query, setQuery] = useState(""); const [platform, setPlatform] = useState("all"); const [state, setState] = useState("all"); const [mode, setMode] = useState("all"); const [environment, setEnvironment] = useState("all"); const [tag, setTag] = useState("all"); const [archive, setArchive] = useState("active"); const [sort, setSort] = useState("attention");
  const environments = [...new Set(bots.map((bot) => bot.environment).filter(Boolean))].sort();
  const tags = [...new Set(bots.flatMap((bot) => bot.tags || []))].sort();
  const filtered = bots.filter((bot) => {
    const documentation = notes.find((note) => note.id === bot.documentationNoteId);
    const relatedMcp = (bot.mcpServerIds || []).map((id) => mcpServers.find((server) => server.id === id)?.name || id);
    const relatedSkills = (bot.skillIds || []).map((id) => skills.find((skill) => skill.id === id)?.name || id);
    const haystack = [bot.name, bot.description, ...(bot.tags || []), ...(bot.connections || []).flatMap((connection) => [connection.username, connection.displayName]), ...(bot.jobs || []).map((job) => job.name), ...(bot.commands || []).flatMap((command) => [command.command, command.description]), ...relatedMcp, ...relatedSkills, documentation?.title, documentation?.body].join(" ").toLowerCase();
    return (!query || haystack.includes(query.toLowerCase())) && (platform === "all" || bot.platforms?.includes(platform)) && (state === "all" || stateOf(bot) === state) && (mode === "all" || bot.executionMode === mode) && (environment === "all" || bot.environment === environment) && (tag === "all" || bot.tags?.includes(tag)) && (archive === "all" || (archive === "archived" ? bot.archivedAt : !bot.archivedAt));
  }).sort((left, right) => {
    if (sort === "name") return left.name.localeCompare(right.name);
    if (sort === "activity") return String(right.runtime?.observedAt || "").localeCompare(String(left.runtime?.observedAt || ""));
    if (sort === "next") { const nextFor = (bot) => upcoming.find((item) => item.botId === bot.id)?.nextRunAt || "9999"; return nextFor(left).localeCompare(nextFor(right)); }
    return (STATE_ORDER[stateOf(left)] ?? 9) - (STATE_ORDER[stateOf(right)] ?? 9);
  });
  return <section className="bot-registry"><header><div><span className="section-kicker">Local operations registry</span><h2>Bot registry</h2></div><span>{filtered.length} of {bots.length}</span></header>
    <div className="bot-filters"><label className="filter-search"><span>⌕</span><input value={query} onChange={(event) => setQuery(event.target.value)} placeholder="Search bots, jobs, commands" aria-label="Search bots" /></label><select value={platform} onChange={(event) => setPlatform(event.target.value)} aria-label="Platform filter"><option value="all">All platforms</option><option value="discord">Discord</option><option value="telegram">Telegram</option></select><select value={state} onChange={(event) => setState(event.target.value)} aria-label="Runtime state filter"><option value="all">All states</option>{Object.entries(STATE_LABELS).map(([value, label]) => <option key={value} value={value}>{label}</option>)}</select><select value={mode} onChange={(event) => setMode(event.target.value)} aria-label="Execution mode filter"><option value="all">All modes</option><option value="continuous">Continuous</option><option value="scheduled">Scheduled</option><option value="webhook">Webhook</option><option value="manual">Manual</option></select><select value={environment} onChange={(event) => setEnvironment(event.target.value)} aria-label="Environment filter"><option value="all">All environments</option>{environments.map((value) => <option key={value}>{value}</option>)}</select><select value={tag} onChange={(event) => setTag(event.target.value)} aria-label="Tag filter"><option value="all">All tags</option>{tags.map((value) => <option key={value}>{value}</option>)}</select><select value={archive} onChange={(event) => setArchive(event.target.value)} aria-label="Archive filter"><option value="active">Active only</option><option value="archived">Archived only</option><option value="all">Active + archived</option></select><select value={sort} onChange={(event) => setSort(event.target.value)} aria-label="Sort bots"><option value="attention">Attention first</option><option value="name">Name</option><option value="activity">Latest activity</option><option value="next">Next run</option></select></div>
    {filtered.length ? <div className="bot-table" role="table" aria-label="Bots"><div className="bot-table-head" role="row"><span>Bot</span><span>State / mode</span><span>Activity / checked</span><span>Next job</span><span>Environment</span><span></span></div>{filtered.map((bot) => { const next = upcoming.find((item) => item.botId === bot.id); const latestRun = bot.runtime?.reportedJobs?.find((item) => item.lastRunAt); return <button className="bot-table-row" role="row" key={bot.id} onClick={() => onOpen(bot.id)}><span className="bot-identity"><span className={`bot-avatar ${bot.platforms?.[0] || "unknown"}`}><Bot size={15} /></span><span><strong>{bot.name}</strong><small>{(bot.connections || []).map((connection) => connection.username ? `@${connection.username}` : connection.displayName).filter(Boolean).join(" · ") || platformLabel(bot.platforms)}</small><em>{bot.description || "No description yet."}</em></span></span><span>{stateBadge(bot)}<small>{bot.executionMode}</small></span><span><strong>{relativeTime(bot.runtime?.observedAt)}</strong><small>Checked {relativeTime(bot.runtime?.lastCheckedAt)}</small></span><span><strong>{next ? relativeTime(next.nextRunAt) : bot.executionMode === "webhook" ? "Event-driven" : "No scheduled jobs"}</strong><small>{next ? `${next.job.name} · ${next.job.timezone}` : latestRun ? `${latestRun.state} ${relativeTime(latestRun.lastRunAt)}` : "No run data"}</small></span><span><strong>{bot.environment}</strong><small>{(bot.tags || []).slice(0, 3).join(" · ") || "No tags"}</small></span><span>Open →</span></button>; })}</div> : <div className="bot-empty compact"><strong>{bots.length ? "No bots match these filters" : "Track your first Discord or Telegram bot"}</strong><span>{bots.length ? "Clear or change filters." : "True health needs a configured HTTP endpoint or local status file. Identity verification alone never marks a bot healthy."}</span>{!bots.length && <button onClick={onAdd}><Plus size={14} /> Add bot</button>}</div>}
  </section>;
}

function DetailField({ label, value, action }) { return <div className="bot-detail-field"><span>{label}</span><strong>{value || "Not configured"}</strong>{action}</div>; }

function BotDetails({ bot, api, notes, mcpServers, skills, upcoming, onBack, onEdit, onChanged, onOpenNote, onOpenSkill, onOpenMcp, onOpenBot }) {
  const [tab, setTab] = useState("overview"); const [activity, setActivity] = useState([]); const [runs, setRuns] = useState([]); const [busy, setBusy] = useState(""); const [message, setMessage] = useState("");
  async function loadHistory() { const [events, savedRuns] = await Promise.all([api.bots.activity(bot.id), api.bots.runs(bot.id)]); setActivity(events); setRuns(savedRuns); }
  useEffect(() => { let active = true; Promise.all([api.bots.activity(bot.id), api.bots.runs(bot.id)]).then(([events, savedRuns]) => { if (active) { setActivity(events); setRuns(savedRuns); } }).catch(() => setMessage("Could not load operational history.")); return () => { active = false; }; }, [bot.id]);
  async function check() { setBusy("check"); setMessage("Checking configured source…"); try { const result = await api.bots.check(bot.id); await Promise.all([onChanged(), loadHistory()]); setMessage(result.skipped ? "No automatic monitoring method configured." : result.ok ? `Check succeeded in ${result.snapshot.responseLatencyMilliseconds} ms.` : result.error.message); } catch (error) { setMessage(error.message || "Check failed."); } finally { setBusy(""); } }
  async function verify(connection) { setBusy(connection.id); setMessage("Verifying platform identity…"); try { const result = await api.bots.verifyConnection(bot.id, connection.id); await onChanged(); setMessage(result.credentialState === "verified" ? "Identity verified. Runtime health is unchanged." : result.credentialErrorSummary); } catch (error) { setMessage(error.message || "Verification failed."); } finally { setBusy(""); } }
  async function archive() { if (!confirm(`${bot.archivedAt ? "Restore" : "Archive"} “${bot.name}”?${bot.archivedAt ? "" : " Automatic checks will stop; documentation and history stay."}`)) return; setBusy("archive"); try { if (bot.archivedAt) await api.bots.restore(bot.id); else await api.bots.archive(bot.id); await onChanged(); } finally { setBusy(""); } }
  const note = notes.find((item) => item.id === bot.documentationNoteId);
  async function openDocumentation() {
    const currentNote = note || (await api.notes.list()).find((item) => item.id === bot.documentationNoteId);
    if (!currentNote) { setMessage("Documentation note could not be found."); return; }
    onOpenNote(currentNote);
  }
  const botUpcoming = upcoming.filter((item) => item.botId === bot.id);
  return <div className="bot-details"><header className="bot-details-header"><button className="bot-back" onClick={onBack}>← Registry</button><div><span className={`bot-avatar large ${bot.platforms?.[0] || "unknown"}`}><Bot size={19} /></span><span><h1>{bot.name}</h1><p>{platformLabel(bot.platforms)} · {bot.environment} · {bot.executionMode}</p></span></div><div className="bot-details-actions"><button onClick={check} disabled={busy === "check"}><RefreshCw size={13} className={busy === "check" ? "spin" : ""} /> Check now</button><button onClick={onEdit}><Settings2 size={13} /> Edit</button><button onClick={archive} disabled={busy === "archive"}><ArchiveRestore size={13} /> {bot.archivedAt ? "Restore" : "Archive"}</button></div></header>
    <div className="bot-truth-row">{stateBadge(bot)}<span><strong>{bot.derivedState?.reason || "No state reason available."}</strong><small>Source: {bot.derivedState?.source || "No source"} · {bot.runtime?.lastCheckedAt ? `checked ${relativeTime(bot.runtime.lastCheckedAt)}` : "never checked"}</small></span><span className={`credential-summary ${bot.connections?.some((connection) => connection.credentialState === "verified") ? "verified" : ""}`}>Identity: {bot.connections?.every((connection) => connection.credentialState === "verified") ? "verified" : bot.connections?.some((connection) => connection.credentialState === "invalid") ? "invalid" : "not verified"}</span></div>
    {message && <p className="bot-message" role="status">{message}</p>}
    <nav className="bot-tabs" aria-label="Bot details sections">{["overview", "jobs", "activity", "commands", "documentation", "connections"].map((value) => <button key={value} className={tab === value ? "active" : ""} onClick={() => setTab(value)}>{value[0].toUpperCase() + value.slice(1)}</button>)}</nav>
    <div className="bot-detail-scroll">
      {tab === "overview" && <><section className="bot-overview-grid"><DetailField label="Runtime state" value={STATE_LABELS[stateOf(bot)]} /><DetailField label="Activity state" value={bot.runtime?.activityState || "Unknown"} /><DetailField label="Last activity" value={bot.runtime?.observedAt ? `${exactTime(bot.runtime.observedAt)} (${relativeTime(bot.runtime.observedAt)})` : "Never observed"} /><DetailField label="Last successful check" value={exactTime(bot.runtime?.lastSuccessfulCheckAt)} /><DetailField label="Last failed check" value={exactTime(bot.runtime?.lastFailedCheckAt)} /><DetailField label="Consecutive failures" value={bot.runtime ? String(bot.runtime.consecutiveFailures || 0) : "No data yet"} /><DetailField label="Freshness" value={bot.runtime?.isStale ? "Stale" : bot.runtime?.observedAt ? "Current within threshold" : "No data yet"} /><DetailField label="Runtime / version" value={[bot.runtimeLanguage || "", bot.runtime?.reportedVersion || bot.version].filter(Boolean).join(" · ") || "Not configured"} /><DetailField label="Start / uptime" value={bot.runtime?.reportedStartedAt ? `${exactTime(bot.runtime.reportedStartedAt)} · ${duration((bot.runtime.reportedUptimeSeconds || 0) * 1000)}` : "Not reported"} /><DetailField label="Created / updated" value={`${exactTime(bot.createdAt)} · ${exactTime(bot.updatedAt)}`} /></section><section className="bot-copy-card"><h2>Purpose</h2><p>{bot.description || "No description yet."}</p><div className="tag-row">{(bot.tags || []).map((value) => <span key={value}>{value}</span>)}</div></section><section className="bot-resource-grid">{[["Repository", "repository", bot.repositoryUrl], ["Project folder", "project", bot.localProjectPath], ["Deployment", "deployment", bot.deploymentUrl], ["Logs", "logs", bot.logsLocation], ["Scheduler", "scheduler", bot.schedulerUrl]].map(([label, kind, value]) => <DetailField key={kind} label={label} value={value} action={value ? <button onClick={() => api.bots.openResource(bot.id, kind)} aria-label={`Open ${label.toLowerCase()}`}><ExternalLink size={12} /></button> : null} />)}</section><p className="monitoring-limitation">Observed health only while Notebook is open. Monitoring resumes when the app is open; this is not 24/7 uptime reporting.</p></>}
      {tab === "jobs" && <section className="bot-job-details">{bot.jobs?.map((job) => { const jobRuns = runs.filter((run) => run.jobId === job.id); const successes = jobRuns.filter((run) => run.status === "success").length; const completed = jobRuns.filter((run) => ["success", "failed"].includes(run.status)).length; const next = botUpcoming.find((item) => item.job.id === job.id); const visualState = job.archivedAt || !job.enabled ? "paused" : next?.health?.state || "unknown"; return <article key={job.id}><header><div><span className={`job-health state-${visualState}`}>{STATE_LABELS[visualState]}</span><h2>{job.name}</h2></div><span>{job.archivedAt ? "Archived" : job.enabled ? "Tracked" : "Tracking disabled"}</span></header><p>{job.description || "No description."}</p><dl><div><dt>Schedule</dt><dd>{job.scheduleType === "cron" ? job.cronExpression : job.scheduleType === "interval" ? `Every ${job.intervalSeconds}s` : job.scheduleType === "oneTime" ? exactTime(job.oneTimeAt, job.timezone) : job.scheduleType}</dd></div><div><dt>Timezone</dt><dd>{job.timezone || "Not applicable"}</dd></div><div><dt>Scheduler source</dt><dd>{job.schedulerSource || "Unknown"}</dd></div><div><dt>Next calculated</dt><dd>{next?.job.nextCalculatedAt ? `${exactTime(next.job.nextCalculatedAt, job.timezone)} · ${relativeTime(next.job.nextCalculatedAt)}` : "No calculated time"}</dd></div><div><dt>Next reported</dt><dd>{next?.job.nextReportedAt ? exactTime(next.job.nextReportedAt, job.timezone) : "Not reported"}</dd></div><div><dt>Latest result</dt><dd>{jobRuns[0]?.status || "No data yet"}</dd></div><div><dt>Latest / expected duration</dt><dd>{duration(jobRuns[0]?.durationMilliseconds)} / {job.expectedDurationSeconds ? duration(job.expectedDurationSeconds * 1000) : "Not set"}</dd></div><div><dt>Observed success rate</dt><dd>{completed ? `${Math.round(successes / completed * 100)}% (${completed} real runs)` : "No data yet"}</dd></div></dl>{next?.job.occurrences?.length ? <div className="occurrence-row">{next.job.occurrences.map((value) => <span key={value}>{exactTime(value, job.timezone)}</span>)}</div> : null}{jobRuns[0]?.redactedErrorSummary && <p className="job-error">{jobRuns[0].redactedErrorSummary}</p>}<small>{job.archivedAt ? "Archived definitions retain history and are excluded from schedule evaluation." : "Enabled here means tracked by Notebook; it does not modify the real scheduler."}</small></article>; })}{!bot.jobs?.length && <p className="bots-section-empty">No job definitions. Event-driven and manual bots may not need schedules.</p>}</section>}
      {tab === "activity" && <section className="bot-timeline">{activity.map((event) => <article key={event.id}><span className={`event-dot ${event.type.includes("failed") || event.type.includes("overdue") ? "danger" : ""}`}></span><div><strong>{EVENT_LABELS[event.type] || event.type.replaceAll("_", " ")}</strong><p>{event.summary}</p><small>{exactTime(event.timestamp)} · {relativeTime(event.timestamp)} · {event.source}</small></div></article>)}{!activity.length && <p className="bots-section-empty">No operational activity yet.</p>}<small className="retention-note">Operational events are bounded locally; secrets and message content are never stored here.</small></section>}
      {tab === "commands" && <section className="bot-commands">{bot.commands?.map((command) => <article key={command.id}><header><code>{command.command}</code><span>{command.platform}</span>{command.deprecated && <span>Deprecated</span>}{!command.enabled && <span>Disabled</span>}</header><p>{command.description || "No description."}</p><dl><div><dt>Usage</dt><dd>{command.usage || "Not documented"}</dd></div><div><dt>Parameters</dt><dd>{command.parameters || "None documented"}</dd></div><div><dt>Permission</dt><dd>{command.permission || "Not documented"}</dd></div><div><dt>Category</dt><dd>{command.category || "General"}</dd></div></dl>{command.notes && <small>{command.notes}</small>}</article>)}{!bot.commands?.length && <p className="bots-section-empty">No commands documented. Edit the bot to add Discord or Telegram commands.</p>}</section>}
      {tab === "documentation" && <section className="bot-documentation"><header><FileText size={18} /><div><h2>{note?.title || "Bot operations note"}</h2><p>Existing Markdown note · one source of truth</p></div><button onClick={openDocumentation}>Open note</button></header><pre>{note?.body || "Documentation note will load from the Notes library."}</pre></section>}
      {tab === "connections" && <section className="bot-connections"><h2>Platform identities</h2>{bot.connections?.map((connection) => <article key={connection.id}><header><span className={`platform-mark ${connection.platform}`}>{connection.platform === "discord" ? "D" : "T"}</span><div><strong>{connection.displayName || connection.username || `${connection.platform} identity`}</strong><small>{connection.username ? `@${connection.username}` : "Username not verified"}</small></div><span className={`credential-state ${connection.credentialState}`}>{connection.credentialState === "verified" ? "Credentials verified" : connection.credentialState === "invalid" ? "Credentials invalid" : "Not verified"}</span></header><dl><div><dt>External bot ID</dt><dd>{connection.externalBotId || "Not configured"}</dd></div><div><dt>Secret reference</dt><dd>{connection.credentialSecretRef || "Not configured"}</dd></div><div><dt>Last verified</dt><dd>{exactTime(connection.credentialVerifiedAt)}</dd></div></dl>{connection.credentialErrorSummary && <p className="job-error">{connection.credentialErrorSummary}</p>}<div className="connection-actions"><button onClick={() => verify(connection)} disabled={busy === connection.id}>{busy === connection.id ? "Verifying…" : "Verify identity"}</button><button onClick={() => api.bots.openSetup(bot.id, connection.id, "portal")}>Open setup</button><button onClick={() => api.bots.openSetup(bot.id, connection.id, "install")}>{connection.platform === "discord" ? "Install to server" : "Open bot"}</button></div><small>Identity verification proves credentials, not whether the real process is running.</small></article>)}<h2>Dependencies</h2><div className="dependency-list"><div><strong>MCP servers</strong>{(bot.mcpServerIds || []).map((id) => { const item = mcpServers.find((server) => server.id === id); return <button key={id} className={!item ? "missing" : ""} onClick={() => item && onOpenMcp(item)}>{item?.name || `Missing reference: ${id}`}</button>; })}{!bot.mcpServerIds?.length && <span>None linked</span>}</div><div><strong>Skills</strong>{(bot.skillIds || []).map((id) => { const item = skills.find((skill) => skill.id === id); return <button key={id} className={!item ? "missing" : ""} onClick={() => item && onOpenSkill(item)}>{item?.name || `Missing reference: ${id}`}</button>; })}{!bot.skillIds?.length && <span>None linked</span>}</div></div></section>}
    </div>
  </div>;
}

function FormField({ label, hint, wide = false, children }) { return <label className={`bot-form-field ${wide ? "wide" : ""}`}><span>{label}</span>{children}{hint && <small>{hint}</small>}</label>; }

function BotForm({ bot, api, mcpServers, skills, onCancel, onSaved }) {
  const [draft, setDraft] = useState(() => editableBot(bot)); const [saving, setSaving] = useState(false); const [error, setError] = useState(""); const [testResult, setTestResult] = useState(null);
  const patch = (value) => setDraft((current) => ({ ...current, ...value }));
  const setMonitoring = (value) => patch({ monitoring: { ...draft.monitoring, ...value } });
  function togglePlatform(platform, enabled) {
    const platforms = enabled ? [...new Set([...draft.platforms, platform])] : draft.platforms.filter((value) => value !== platform);
    const connections = enabled ? (draft.connections.some((item) => item.platform === platform) ? draft.connections : [...draft.connections, defaultConnection(platform)]) : draft.connections.filter((item) => item.platform !== platform);
    patch({ platforms, connections });
  }
  function updateConnection(platform, value) { patch({ connections: draft.connections.map((item) => item.platform === platform ? { ...item, ...value } : item) }); }
  function updateJob(id, value) { patch({ jobs: draft.jobs.map((item) => item.id === id ? { ...item, ...value } : item) }); }
  function updateCommand(id, value) { patch({ commands: draft.commands.map((item) => item.id === id ? { ...item, ...value } : item) }); }
  function validate() {
    if (!draft.name.trim()) return "Name is required.";
    if (!draft.platforms.length) return "Select Discord, Telegram, or both.";
    if (draft.executionMode === "scheduled" && !draft.jobs.some((job) => job.enabled && !job.archivedAt)) return "Scheduled bots require at least one tracked, non-archived job.";
    if (["http-health", "http-status"].includes(draft.monitoring.adapter) && !draft.monitoring.url) return "Monitoring URL is required.";
    if (draft.monitoring.adapter === "http-status" && draft.monitoring.httpMethod === "HEAD") return "Structured status monitoring requires GET so JSON can be validated.";
    if (draft.monitoring.adapter === "local-status" && !draft.monitoring.filePath) return "Status-file path is required.";
    const names = draft.jobs.map((job) => job.name.trim().toLowerCase()); if (names.some((value) => !value) || new Set(names).size !== names.length) return "Every job needs a unique name.";
    for (const job of draft.jobs) { try { cronPreview(job); } catch (reason) { return `${job.name || "Job"}: ${reason.message}`; } }
    if (draft.commands.some((command) => !command.command.trim())) return "Every documented command needs a command name.";
    return "";
  }
  async function save(event) { event.preventDefault(); const invalid = validate(); if (invalid) { setError(invalid); return; } setSaving(true); setError(""); try { const saved = bot ? await api.bots.update(bot.id, draft) : await api.bots.create(draft); await onSaved(saved); } catch (reason) { setError(reason.message || "Could not save bot."); } finally { setSaving(false); } }
  async function testMonitoring() { const invalid = validate(); if (invalid && !invalid.includes("Scheduled bots")) { setTestResult({ ok: false, error: { message: invalid } }); return; } setTestResult({ loading: true }); try { setTestResult(await api.bots.testMonitoring(draft)); } catch (reason) { setTestResult({ ok: false, error: { message: reason.message || "Monitoring test failed." } }); } }
  return <div className="bot-form-overlay" role="dialog" aria-modal="true" aria-label={bot ? "Edit bot" : "Add bot"}><form className="bot-form" onSubmit={save}><header><div><span className="section-kicker">Local bot registry</span><h1>{bot ? `Edit ${bot.name}` : "Add bot"}</h1><p>Definitions and runbook stay local. Store secret references only—never tokens.</p></div><button type="button" onClick={onCancel} aria-label="Close bot form"><X size={17} /></button></header><div className="bot-form-scroll">
    {error && <p className="bot-form-error" role="alert">{error}</p>}
    <fieldset><legend>Basics</legend><div className="bot-form-grid"><FormField label="Name"><input value={draft.name} onChange={(event) => patch({ name: event.target.value })} aria-label="Bot name" /></FormField><FormField label="Execution mode"><select value={draft.executionMode} onChange={(event) => patch({ executionMode: event.target.value })} aria-label="Execution mode"><option value="continuous">Continuous</option><option value="scheduled">Scheduled</option><option value="webhook">Webhook</option><option value="manual">Manual</option></select></FormField><FormField label="Environment"><input value={draft.environment} onChange={(event) => patch({ environment: event.target.value })} aria-label="Bot environment" /></FormField><FormField label="Tags" hint="Comma-separated"><input value={draft.tags.join(", ")} onChange={(event) => patch({ tags: event.target.value.split(",").map((value) => value.trim()).filter(Boolean) })} aria-label="Bot tags" /></FormField><FormField label="Description" wide><textarea value={draft.description} onChange={(event) => patch({ description: event.target.value })} aria-label="Bot description" rows="3" /></FormField><div className="bot-platform-checks"><span>Platforms</span>{["discord", "telegram"].map((platform) => <label key={platform}><input type="checkbox" checked={draft.platforms.includes(platform)} onChange={(event) => togglePlatform(platform, event.target.checked)} /><span>{platform === "discord" ? "Discord" : "Telegram"}</span></label>)}</div></div></fieldset>
    <fieldset><legend>Platform connections</legend>{draft.connections.map((connection) => <div className="connection-form" key={connection.id}><header><span className={`platform-mark ${connection.platform}`}>{connection.platform === "discord" ? "D" : "T"}</span><strong>{connection.platform === "discord" ? "Discord" : "Telegram"}</strong></header><div className="bot-form-grid"><FormField label="Display name"><input value={connection.displayName || ""} onChange={(event) => updateConnection(connection.platform, { displayName: event.target.value })} aria-label={`${connection.platform} display name`} /></FormField><FormField label="Username / handle"><input value={connection.username || ""} onChange={(event) => updateConnection(connection.platform, { username: event.target.value.replace(/^@/, "") })} aria-label={`${connection.platform} username`} /></FormField><FormField label="External bot / application ID"><input value={connection.externalBotId || ""} onChange={(event) => updateConnection(connection.platform, { externalBotId: event.target.value })} aria-label={`${connection.platform} external bot ID`} /></FormField><FormField label="Credential secret reference" hint="Environment-variable name; token stays in main process"><input value={connection.credentialSecretRef || ""} onChange={(event) => updateConnection(connection.platform, { credentialSecretRef: event.target.value.toUpperCase() })} placeholder={connection.platform === "discord" ? "DISCORD_MY_BOT_TOKEN" : "TELEGRAM_MY_BOT_TOKEN"} aria-label={`${connection.platform} credential secret reference`} /></FormField>{connection.platform === "discord" && <FormField label="Install permission bitfield" hint="Request only permissions the bot needs"><input value={connection.installPermissions || "0"} onChange={(event) => updateConnection(connection.platform, { installPermissions: event.target.value })} aria-label="Discord install permissions" /></FormField>}<FormField label="Avatar URL"><input value={connection.avatarUrl || ""} onChange={(event) => updateConnection(connection.platform, { avatarUrl: event.target.value })} aria-label={`${connection.platform} avatar URL`} /></FormField></div></div>)}</fieldset>
    <fieldset><legend>Project and deployment</legend><div className="bot-form-grid"><FormField label="Repository URL"><input value={draft.repositoryUrl || ""} onChange={(event) => patch({ repositoryUrl: event.target.value })} aria-label="Repository URL" /></FormField><FormField label="Local project folder"><input value={draft.localProjectPath || ""} onChange={(event) => patch({ localProjectPath: event.target.value })} aria-label="Local project folder" /></FormField><FormField label="Runtime / language"><input value={draft.runtime || ""} onChange={(event) => patch({ runtime: event.target.value })} aria-label="Runtime language" /></FormField><FormField label="Version"><input value={draft.version || ""} onChange={(event) => patch({ version: event.target.value })} aria-label="Bot version" /></FormField><FormField label="Hosting provider"><input value={draft.hostingProvider || ""} onChange={(event) => patch({ hostingProvider: event.target.value })} aria-label="Hosting provider" /></FormField><FormField label="Deployment URL"><input value={draft.deploymentUrl || ""} onChange={(event) => patch({ deploymentUrl: event.target.value })} aria-label="Deployment URL" /></FormField><FormField label="Logs URL or local path"><input value={draft.logsLocation || ""} onChange={(event) => patch({ logsLocation: event.target.value })} aria-label="Logs location" /></FormField><FormField label="Scheduler URL"><input value={draft.schedulerUrl || ""} onChange={(event) => patch({ schedulerUrl: event.target.value })} aria-label="Scheduler URL" /></FormField></div></fieldset>
    <fieldset><legend>Monitoring</legend><p className="fieldset-copy">Checks run only while Notebook is open. Credential verification and runtime health remain separate.</p><div className="bot-form-grid"><FormField label="Monitoring adapter"><select value={draft.monitoring.adapter} onChange={(event) => setMonitoring({ adapter: event.target.value })} aria-label="Monitoring adapter"><option value="manual">Manual / none</option><option value="http-health">Simple HTTP health</option><option value="http-status">Structured HTTP status</option><option value="local-status">Local status file</option></select></FormField>{["http-health", "http-status"].includes(draft.monitoring.adapter) && <FormField label="Status or health URL"><input value={draft.monitoring.url || ""} onChange={(event) => setMonitoring({ url: event.target.value })} aria-label="Monitoring URL" /></FormField>}{["http-health", "http-status"].includes(draft.monitoring.adapter) && <FormField label="HTTP method"><select value={draft.monitoring.httpMethod || "GET"} onChange={(event) => setMonitoring({ httpMethod: event.target.value })} aria-label="Monitoring HTTP method"><option value="GET">GET</option><option value="HEAD">HEAD</option></select></FormField>}{draft.monitoring.adapter === "local-status" && <FormField label="Status-file path"><input value={draft.monitoring.filePath || ""} onChange={(event) => setMonitoring({ filePath: event.target.value })} aria-label="Status file path" /></FormField>}<FormField label="Authentication secret reference"><input value={draft.monitoring.authSecretRef || ""} onChange={(event) => setMonitoring({ authSecretRef: event.target.value.toUpperCase() })} aria-label="Monitoring authentication secret reference" /></FormField><FormField label="Check interval (seconds)"><input type="number" min="30" max="86400" value={draft.monitoring.intervalSeconds} onChange={(event) => setMonitoring({ intervalSeconds: Number(event.target.value) })} aria-label="Check interval seconds" /></FormField><FormField label="Timeout (milliseconds)"><input type="number" min="250" max="60000" value={draft.monitoring.timeoutMilliseconds} onChange={(event) => setMonitoring({ timeoutMilliseconds: Number(event.target.value) })} aria-label="Request timeout milliseconds" /></FormField><FormField label="Stale after (seconds)"><input type="number" min="30" value={draft.monitoring.staleAfterSeconds} onChange={(event) => setMonitoring({ staleAfterSeconds: Number(event.target.value) })} aria-label="Stale threshold seconds" /></FormField><FormField label="Failures before offline"><input type="number" min="1" max="20" value={draft.monitoring.failuresBeforeOffline} onChange={(event) => setMonitoring({ failuresBeforeOffline: Number(event.target.value) })} aria-label="Failures before offline" /></FormField>{draft.monitoring.adapter === "http-health" && <FormField label="Expected HTTP code" hint="Blank accepts any 2xx"><input type="number" min="100" max="599" value={draft.monitoring.expectedResponseCode ?? ""} onChange={(event) => setMonitoring({ expectedResponseCode: event.target.value ? Number(event.target.value) : "" })} aria-label="Expected HTTP response code" /></FormField>}</div><label className="tracking-toggle"><input type="checkbox" checked={draft.monitoring.monitoringEnabled} onChange={(event) => setMonitoring({ monitoringEnabled: event.target.checked })} /><span>Monitoring enabled while Notebook is open</span></label><div className="monitor-test-row"><button type="button" onClick={testMonitoring} disabled={testResult?.loading}>{testResult?.loading ? "Testing…" : "Test monitoring"}</button>{testResult && !testResult.loading && <span className={testResult.ok ? "success" : "failed"}>{testResult.ok ? `${testResult.source} succeeded${testResult.latencyMilliseconds != null ? ` in ${testResult.latencyMilliseconds} ms` : ""}. ${testResult.parsedStatus?.state || ""} ${testResult.parsedStatus?.message || ""}` : testResult.error?.message}</span>}</div></fieldset>
    <fieldset><legend>Jobs</legend><p className="fieldset-copy">Definitions track the real scheduler. Enabled means tracked here; Notebook does not start, stop, or reschedule the real job.</p>{draft.jobs.map((job) => { let preview; let previewError; try { preview = cronPreview(job); } catch (reason) { previewError = reason.message; } return <div className="job-form" key={job.id}><header><input value={job.name} onChange={(event) => updateJob(job.id, { name: event.target.value })} placeholder="Job name" aria-label="Job name" />{job.createdAt ? <button type="button" onClick={() => updateJob(job.id, { archivedAt: job.archivedAt ? null : new Date().toISOString() })} aria-label={`${job.archivedAt ? "Restore" : "Archive"} ${job.name || "job"}`}><ArchiveRestore size={14} /></button> : <button type="button" onClick={() => patch({ jobs: draft.jobs.filter((item) => item.id !== job.id) })} aria-label={`Remove ${job.name || "job"}`}><X size={14} /></button>}</header><div className="bot-form-grid"><FormField label="Schedule type"><select value={job.scheduleType} onChange={(event) => updateJob(job.id, { scheduleType: event.target.value })} aria-label={`Schedule type for ${job.name || "job"}`}><option value="cron">Cron</option><option value="interval">Interval</option><option value="oneTime">One time</option><option value="external">External</option><option value="manual">Manual</option></select></FormField>{job.scheduleType === "cron" && <><FormField label="Cron expression"><input value={job.cronExpression || ""} onChange={(event) => updateJob(job.id, { cronExpression: event.target.value })} aria-label={`Cron expression for ${job.name || "job"}`} /></FormField><FormField label="IANA timezone"><input value={job.timezone || ""} onChange={(event) => updateJob(job.id, { timezone: event.target.value })} aria-label={`Timezone for ${job.name || "job"}`} /></FormField></>}{job.scheduleType === "interval" && <FormField label="Interval seconds"><input type="number" min="1" value={job.intervalSeconds || ""} onChange={(event) => updateJob(job.id, { intervalSeconds: Number(event.target.value) })} aria-label={`Interval for ${job.name || "job"}`} /></FormField>}{job.scheduleType === "oneTime" && <FormField label="One-time ISO date"><input value={job.oneTimeAt || ""} onChange={(event) => updateJob(job.id, { oneTimeAt: event.target.value })} placeholder="2026-08-18T14:00:00.000Z" aria-label={`One time date for ${job.name || "job"}`} /></FormField>}<FormField label="Scheduler source"><select value={job.schedulerSource} onChange={(event) => updateJob(job.id, { schedulerSource: event.target.value })} aria-label={`Scheduler source for ${job.name || "job"}`}>{SCHEDULER_SOURCES.map((value) => <option key={value}>{value}</option>)}</select></FormField><FormField label="Grace period seconds"><input type="number" min="0" value={job.gracePeriodSeconds ?? 0} onChange={(event) => updateJob(job.id, { gracePeriodSeconds: Number(event.target.value) })} aria-label={`Grace period for ${job.name || "job"}`} /></FormField><FormField label="Expected duration seconds"><input type="number" min="1" value={job.expectedDurationSeconds || ""} onChange={(event) => updateJob(job.id, { expectedDurationSeconds: Number(event.target.value) })} aria-label={`Expected duration for ${job.name || "job"}`} /></FormField><FormField label="Description" wide><textarea value={job.description || ""} onChange={(event) => updateJob(job.id, { description: event.target.value })} aria-label={`Description for ${job.name || "job"}`} rows="2" /></FormField></div><div className={`schedule-preview ${previewError ? "failed" : ""}`}><strong>{previewError ? "Invalid schedule" : "Next three occurrences"}</strong>{previewError ? <span>{previewError}</span> : preview.values.length ? preview.values.map((value) => <span key={value}>{exactTime(value, job.timezone)} · {job.timezone}</span>) : <span>{preview.label}</span>}</div><div className="job-toggles"><label><input type="checkbox" checked={job.enabled} onChange={(event) => updateJob(job.id, { enabled: event.target.checked })} /> Track job</label><label><input type="checkbox" checked={job.critical} onChange={(event) => updateJob(job.id, { critical: event.target.checked })} /> Critical job</label>{job.archivedAt && <span>Archived definition; history retained</span>}</div></div>; })}<button type="button" className="add-inline" onClick={() => patch({ jobs: [...draft.jobs, defaultJob(Intl.DateTimeFormat().resolvedOptions().timeZone || "UTC")] })}><Plus size={13} /> Add job</button></fieldset>
    <fieldset><legend>Commands</legend>{draft.commands.map((command) => <div className="command-form" key={command.id}><header><input value={command.command} onChange={(event) => updateCommand(command.id, { command: event.target.value })} placeholder="/command" aria-label="Command name" /><select value={command.platform} onChange={(event) => updateCommand(command.id, { platform: event.target.value })} aria-label={`Platform for ${command.command || "command"}`}>{draft.platforms.map((platform) => <option key={platform}>{platform}</option>)}</select><button type="button" onClick={() => patch({ commands: draft.commands.filter((item) => item.id !== command.id) })} aria-label={`Remove ${command.command || "command"}`}><X size={14} /></button></header><div className="bot-form-grid"><FormField label="Description"><input value={command.description || ""} onChange={(event) => updateCommand(command.id, { description: event.target.value })} aria-label={`Description for ${command.command || "command"}`} /></FormField><FormField label="Usage"><input value={command.usage || ""} onChange={(event) => updateCommand(command.id, { usage: event.target.value })} aria-label={`Usage for ${command.command || "command"}`} /></FormField><FormField label="Parameters"><input value={command.parameters || ""} onChange={(event) => updateCommand(command.id, { parameters: event.target.value })} aria-label={`Parameters for ${command.command || "command"}`} /></FormField><FormField label="Permission"><input value={command.permission || ""} onChange={(event) => updateCommand(command.id, { permission: event.target.value })} aria-label={`Permission for ${command.command || "command"}`} /></FormField><FormField label="Category"><input value={command.category || ""} onChange={(event) => updateCommand(command.id, { category: event.target.value })} aria-label={`Category for ${command.command || "command"}`} /></FormField><FormField label="Notes" wide><textarea value={command.notes || ""} onChange={(event) => updateCommand(command.id, { notes: event.target.value })} aria-label={`Notes for ${command.command || "command"}`} rows="2" /></FormField></div><div className="job-toggles"><label><input type="checkbox" checked={command.enabled !== false} onChange={(event) => updateCommand(command.id, { enabled: event.target.checked })} /> Enabled</label><label><input type="checkbox" checked={Boolean(command.deprecated)} onChange={(event) => updateCommand(command.id, { deprecated: event.target.checked })} /> Deprecated</label></div></div>)}<button type="button" className="add-inline" onClick={() => patch({ commands: [...draft.commands, defaultCommand(draft.platforms[0])] })}><Plus size={13} /> Add command</button></fieldset>
    <fieldset><legend>Relationships</legend><div className="relationship-pickers"><div><strong>MCP servers</strong>{mcpServers.map((server) => <label key={server.id}><input type="checkbox" checked={draft.mcpServerIds.includes(server.id)} onChange={(event) => patch({ mcpServerIds: event.target.checked ? [...draft.mcpServerIds, server.id] : draft.mcpServerIds.filter((id) => id !== server.id) })} /><span>{server.name}</span></label>)}{!mcpServers.length && <span>No MCP servers registered yet.</span>}</div><div><strong>Skills</strong>{skills.map((skill) => <label key={skill.id}><input type="checkbox" checked={draft.skillIds.includes(skill.id)} onChange={(event) => patch({ skillIds: event.target.checked ? [...draft.skillIds, skill.id] : draft.skillIds.filter((id) => id !== skill.id) })} /><span>{skill.name || "Untitled skill"}</span></label>)}</div></div></fieldset>
    <fieldset><legend>Documentation</legend><p className="fieldset-copy">Saving creates or keeps one Markdown note with purpose, setup, development, deployment, recovery, troubleshooting, logs, and ownership sections. Existing note content is preserved.</p></fieldset>
  </div><footer><button type="button" onClick={onCancel}>Cancel</button><button type="submit" disabled={saving}>{saving ? "Saving…" : bot ? "Save changes" : "Add bot"}</button></footer></form></div>;
}

export function BotsWorkspace({ api, bots, mcpServers, skills, notes, currentId, onCurrent, onBotsChange, onNotesChange, onOpenNote, onOpenSkill, onOpenMcp, onHide }) {
  const [loading, setLoading] = useState(true); const [upcoming, setUpcoming] = useState([]); const [formBot, setFormBot] = useState(null); const [formOpen, setFormOpen] = useState(false); const [refreshing, setRefreshing] = useState(false); const [refreshMessage, setRefreshMessage] = useState("");
  const selected = bots.find((bot) => bot.id === currentId) || null;
  async function reload() { const [savedUpcoming] = await Promise.all([api.bots.upcoming(50), onBotsChange()]); setUpcoming(savedUpcoming); setLoading(false); }
  useEffect(() => { reload().catch(() => { setLoading(false); setRefreshMessage("Could not load bot operations."); }); }, []);
  useEffect(() => { api.bots.upcoming(50).then(setUpcoming).catch(() => {}); }, [bots]);
  async function refreshAll() { if (refreshing) return; setRefreshing(true); setRefreshMessage("Checking configured bots…"); try { const result = await api.bots.checkAll(); await reload(); setRefreshMessage(`Checked ${result.checked}: ${result.succeeded} succeeded, ${result.failed} failed.`); } catch (reason) { setRefreshMessage(reason.message || "Refresh failed."); } finally { setRefreshing(false); } }
  function openForm(bot = null) { setFormBot(bot); setFormOpen(true); }
  async function saved(bot) { setFormOpen(false); await Promise.all([reload(), onNotesChange?.()]); onCurrent(bot.id); }
  if (loading) return <section className="bots-page bots-loading"><header><div><span className="section-kicker">Automation</span><h1>Bots</h1><p>Loading local registry and operational state…</p></div></header><div className="bots-skeleton"></div></section>;
  if (selected) return <section className="bots-page"><BotDetails bot={selected} api={api} notes={notes} mcpServers={mcpServers} skills={skills} upcoming={upcoming} onBack={() => onCurrent(null)} onEdit={() => openForm(selected)} onChanged={reload} onOpenNote={onOpenNote} onOpenSkill={onOpenSkill} onOpenMcp={onOpenMcp} onOpenBot={onCurrent} />{formOpen && <BotForm bot={formBot} api={api} mcpServers={mcpServers} skills={skills} onCancel={() => setFormOpen(false)} onSaved={saved} />}</section>;
  return <section className="bots-page"><header className="bots-page-header"><div><span className="section-kicker">Automation</span><h1>Bots</h1><p>Discord and Telegram registry, runbooks, app-open health checks, and schedule evidence.</p></div><div><button onClick={refreshAll} disabled={refreshing}><RefreshCw size={13} className={refreshing ? "spin" : ""} /> {refreshing ? "Refreshing…" : "Refresh all"}</button><button className="primary" onClick={() => openForm()}><Plus size={13} /> Add bot</button><button className="hide" onClick={onHide} aria-label="Hide notebook">×</button></div></header>{refreshMessage && <p className="bot-refresh-message" role="status">{refreshMessage}</p>}<div className="bots-page-scroll"><SummaryStrip bots={bots} upcoming={upcoming} />{!bots.length ? <div className="bot-empty"><Bot size={28} /><strong>No bots registered</strong><span>Track purpose, platform identity, health evidence, schedules, commands, dependencies, and a Markdown runbook. True runtime health requires an HTTP endpoint or local status file.</span><button onClick={() => openForm()}><Plus size={14} /> Add bot</button></div> : <><AttentionArea bots={bots} onOpen={onCurrent} /><UpcomingJobs upcoming={upcoming} onOpen={onCurrent} /><BotRegistry bots={bots} upcoming={upcoming} mcpServers={mcpServers} skills={skills} notes={notes} onOpen={onCurrent} onAdd={() => openForm()} /></>}</div>{formOpen && <BotForm bot={formBot} api={api} mcpServers={mcpServers} skills={skills} onCancel={() => setFormOpen(false)} onSaved={saved} />}</section>;
}

export function McpSidebar({ servers, currentId, onSelect }) { return <div className="bot-sidebar-list"><div className="bot-sidebar-summary"><strong>{servers.length} servers</strong><span>Reusable dependencies</span></div>{servers.map((server) => <button key={server.id} className={currentId === server.id ? "active" : ""} onClick={() => onSelect(server.id)}><span className="platform-dot mcp"><ServerCog size={12} /></span><span><strong>{server.name}</strong><small>{server.transport || "stdio"}</small></span></button>)}{!servers.length && <p>No MCP servers yet.</p>}</div>; }

export function McpServersWorkspace({ api, servers, bots, currentId, onCurrent, onServersChange, onOpenBot, onHide }) {
  const current = servers.find((server) => server.id === currentId) || null; const [draft, setDraft] = useState(current || { name: "", description: "", transport: "stdio", command: "", url: "", body: "" }); const [creating, setCreating] = useState(!current); const [message, setMessage] = useState("");
  useEffect(() => { if (current) { setDraft(current); setCreating(false); } }, [currentId, servers]);
  async function save(event) { event.preventDefault(); setMessage("Saving…"); try { const saved = creating ? await api.mcpServers.create(draft) : await api.mcpServers.update(current.id, draft); await onServersChange(); onCurrent(saved.id); setCreating(false); setMessage("Saved"); } catch (reason) { setMessage(reason.message || "Could not save MCP server."); } }
  async function remove() { if (!current || !confirm(`Delete “${current.name}”? Bot relation IDs will remain visible as missing references.`)) return; await api.mcpServers.remove(current.id); await onServersChange(); onCurrent(null); setDraft({ name: "", description: "", transport: "stdio", command: "", url: "", body: "" }); setCreating(true); }
  const usedBy = current ? bots.filter((bot) => bot.mcpServerIds?.includes(current.id)) : [];
  return <section className="mcp-page"><header className="bots-page-header"><div><span className="section-kicker">Automation</span><h1>MCP Servers</h1><p>Reusable local tool-server records. Bots link by stable ID.</p></div><div><button onClick={() => { setDraft({ name: "", description: "", transport: "stdio", command: "", url: "", body: "" }); setCreating(true); onCurrent(null); }}><Plus size={13} /> Add server</button><button className="hide" onClick={onHide} aria-label="Hide notebook">×</button></div></header><form className="mcp-editor" onSubmit={save}><div className="bot-form-grid"><FormField label="Name"><input value={draft.name || ""} onChange={(event) => setDraft({ ...draft, name: event.target.value })} aria-label="MCP server name" required /></FormField><FormField label="Transport"><select value={draft.transport || "stdio"} onChange={(event) => setDraft({ ...draft, transport: event.target.value })} aria-label="MCP transport"><option value="stdio">stdio</option><option value="http">HTTP</option><option value="sse">SSE</option></select></FormField><FormField label="Command"><input value={draft.command || ""} onChange={(event) => setDraft({ ...draft, command: event.target.value })} aria-label="MCP command" /></FormField><FormField label="URL"><input value={draft.url || ""} onChange={(event) => setDraft({ ...draft, url: event.target.value })} aria-label="MCP URL" /></FormField><FormField label="Description" wide><textarea value={draft.description || ""} onChange={(event) => setDraft({ ...draft, description: event.target.value })} aria-label="MCP description" rows="3" /></FormField><FormField label="Notes" wide><textarea value={draft.body || ""} onChange={(event) => setDraft({ ...draft, body: event.target.value })} aria-label="MCP notes" rows="9" /></FormField></div><section className="used-by-bots"><strong>Used by bots</strong>{usedBy.map((bot) => <button type="button" key={bot.id} onClick={() => onOpenBot(bot.id)}>{bot.name}</button>)}{current && !usedBy.length && <span>No linked bots</span>}</section>{message && <p className="bot-message">{message}</p>}<footer>{current && <button type="button" className="danger" onClick={remove}>Delete</button>}<button type="submit">{creating ? "Add MCP server" : "Save changes"}</button></footer></form></section>;
}
